using System;
using System.Text.RegularExpressions;
using UnityEngine;
using UnityEngine.UI;
using TMPro;
namespace LWS.TruckSports {
// Read-only presentation adapter over the sport's existing authoritative standings.
// Updates only when its text/roster changes; no rules, scores or eligibility are inferred here.
[DefaultExecutionOrder(220)]public sealed class SportsBroadcastScores:MonoBehaviour {
 public SportsEventMenus menus;public TMP_FontAsset headingFont,bodyFont;
 sealed class Card {public GameObject root;public TMP_Text name,value,detail;public Image stripe;}
 Card[] cards;string prior;float next;RectTransform root;bool mapped;
 TMP_Text Text(Transform parent,string name,Vector2 position,Vector2 size,int font,bool bold){var g=new GameObject(name,typeof(RectTransform));g.transform.SetParent(parent,false);var r=g.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=r.pivot=new Vector2(0,1);r.anchoredPosition=position;r.sizeDelta=size;var text=g.AddComponent<TextMeshProUGUI>();text.font=bold?headingFont:bodyFont;text.fontSize=font;text.enableAutoSizing=true;text.fontSizeMin=font-2;text.fontSizeMax=font;text.color=SportsBroadcastCanvas.Cream;text.raycastTarget=false;text.alignment=TextAlignmentOptions.MidlineLeft;text.overflowMode=TextOverflowModes.Ellipsis;return text;}
 void Build(){var holder=new GameObject("Broadcast participant cards",typeof(RectTransform));root=holder.GetComponent<RectTransform>();root.SetParent(menus.hud.transform,false);root.anchorMin=root.anchorMax=root.pivot=new Vector2(0,1);root.anchoredPosition=new Vector2(16,-76);root.sizeDelta=new Vector2(345,820);cards=new Card[menus.match.MaximumPlayers];for(int i=0;i<cards.Length;i++){var g=new GameObject("Participant card "+i,typeof(RectTransform),typeof(Image),typeof(SportsBroadcastPlate));g.transform.SetParent(root,false);var rect=g.GetComponent<RectTransform>();rect.anchorMin=rect.anchorMax=rect.pivot=new Vector2(0,1);rect.anchoredPosition=new Vector2(0,-i*65);rect.sizeDelta=new Vector2(345,60);g.GetComponent<Image>().color=SportsBroadcastCanvas.Ink;var stripe=new GameObject("Participant color",typeof(RectTransform),typeof(Image));stripe.transform.SetParent(g.transform,false);var sr=stripe.GetComponent<RectTransform>();sr.anchorMin=new Vector2(0,0);sr.anchorMax=new Vector2(0,1);sr.pivot=new Vector2(0,.5f);sr.offsetMin=new Vector2(0,6);sr.offsetMax=new Vector2(4,-6);cards[i]=new Card{root=g,stripe=stripe.GetComponent<Image>(),name=Text(g.transform,"Name",new Vector2(13,-3),new Vector2(260,27),23,true),value=Text(g.transform,"Score badge",new Vector2(277,-6),new Vector2(60,46),30,true),detail=Text(g.transform,"Status",new Vector2(13,-30),new Vector2(260,25),20,false)};cards[i].value.alignment=TextAlignmentOptions.Center;}}
 void LateUpdate(){if(menus==null||headingFont==null||bodyFont==null)return;if(cards==null)Build();bool showing=menus.Screen==SportsEventScreen.Play&&!menus.match.MultiViewHUD;root.gameObject.SetActive(showing&&mapped);if(!showing)return;if(Time.unscaledTime<next)return;next=Time.unscaledTime+.1f;string source=menus.standings.text;bool found=false;for(int i=0;i<menus.match.setup.count;i++)if(source.Contains(menus.match.setup.players[i].name)){found=true;break;}mapped=found;root.gameObject.SetActive(found);menus.standings.gameObject.SetActive(!found);if(!found||source==prior)return;prior=source;source=Regex.Replace(source,"<[^>]*>","");var lines=source.Replace("    |    ","\n").Split('\n');for(int i=0;i<cards.Length;i++){var card=cards[i];bool active=i<menus.match.setup.count;card.root.SetActive(active);if(!active)continue;var player=menus.match.setup.players[i];card.name.text=player.name;card.name.color=card.stripe.color=player.color;string detail="";foreach(var line in lines){int at=line.IndexOf(player.name,StringComparison.Ordinal);if(at>=0){detail=line.Substring(at+player.name.Length).Trim(' ','·','|');break;}}var number=Regex.Match(detail,@"^[-+]?\d+(?:\.\d+)?");card.value.text=number.Success?number.Value:"P"+(i+1);card.detail.text=number.Success?detail.Substring(number.Length).Trim():detail;if(card.detail.text.Length==0)card.detail.text="READY";}}
}
}
